<link rel="stylesheet" href="<?=asset('css/communication.css')?>">
<main class="booking-shell"><header><span class="eyebrow">A conversation can be a starting point</span><h1>Book time with Waithaka</h1><p>Explore an idea, discuss a partnership or start a useful conversation.</p></header>
<?php foreach(flashes()as$f):?><p class="notice" role="status"><?=e($f['message'])?></p><?php endforeach;?><?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?>
<?php if($manage):?><section class="comm-panel"><span class="comm-badge"><?=e($manage['status'])?></span><h2><?=e($cfg['types'][$manage['type']]['name'])?></h2><p>Hello <?=e($manage['first'])?>. <?=e((new DateTimeImmutable('@'.$manage['start']))->setTimezone(comm_zone($manage['timezone']))->format('l, j F Y · H:i T'))?></p><?php if($manage['status']==='requested'):?><p>Your proposed time is reserved while Waithaka reviews your request. It is not yet a confirmed appointment.</p><?php elseif($manage['status']==='confirmed'):?><p>Your appointment is confirmed. Calendar invitations and service emails are processed separately.</p><?php if($manage['join']):?><a class="wbtn primary" href="<?=e($manage['join'])?>" rel="noopener noreferrer" target="_blank">Join meeting</a><?php endif;?><?php elseif($manage['status']==='review'):?><p>Your request is saved and needs calendar review. Please contact Waithaka before submitting again.</p><?php endif;?><?php if(in_array($manage['status'],['requested','confirmed'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><button class="wbtn" data-confirm-action="Cancel this booking?">Cancel booking</button></form><?php endif;?><p class="comm-muted">Keep this private link to manage your booking. It is not a newsletter subscription.</p></section><?php endif;?>
<?php if(empty($cfg['enabled'])):?><section class="comm-panel"><h2>Start with a message</h2><p>Online booking is not open yet. Send your preferred times and the purpose of your conversation.</p><a class="wbtn primary" href="<?=url('/contact')?>">Contact Waithaka</a></section>
<?php elseif(!$manage||in_array($manage['status'],['requested','confirmed'],true)):?>
<div class="booking-grid"><aside class="comm-panel"><h2><?=$manage?'Choose a new time':'1. Choose a conversation'?></h2><?php if(!$manage):?><?php foreach($cfg['types']as$k=>$t):if(empty($t['enabled']))continue;?><a class="booking-type" href="<?=url('/book?'.http_build_query(['type'=>$k,'date'=>$date,'timezone'=>$zone]))?>" <?=$type===$k?'aria-current="true"':''?>><strong><?=e($t['name'])?></strong><span><?=(int)$t['minutes']?> minutes · <?=!empty($t['approval'])?'Subject to approval':'Instant confirmation'?></span></a><?php endforeach;?><?php else:?><p><?=e($cfg['types'][$type]['name'])?></p><?php endif;?><p>Availability is checked across Waithaka’s selected calendars. Your timezone can be changed below.</p></aside>
<section class="comm-panel"><h2><?=$manage?'Reschedule':'2. Find a time'?></h2><form method="get" class="comm-fields"><input type="hidden" name="type" value="<?=e($type)?>"><label>Date in host timezone (<?=e($cfg['timezone'])?>)<input type="date" name="date" value="<?=e($date)?>" required></label><label>Show times in<select name="timezone" data-visitor-timezone><?php foreach(DateTimeZone::listIdentifiers()as$tz):?><option <?=$zone===$tz?'selected':''?>><?=e($tz)?></option><?php endforeach;?></select></label><button class="wbtn">Show available times</button></form>
<?php if(!$slots):?><p class="comm-empty">No verified times available for this date. Try another date or <a href="<?=url('/contact')?>">send a message</a>.</p><?php else:?><form method="post" class="booking-form"><?=csrf_field()?><input type="hidden" name="type" value="<?=e($type)?>"><input type="hidden" name="date" value="<?=e($date)?>"><input type="hidden" name="timezone" value="<?=e($zone)?>"><input type="hidden" name="request_id" value="<?=bin2hex(random_bytes(16))?>"><?php if($manage):?><input type="hidden" name="action" value="reschedule"><?php endif;?><fieldset><legend>Available start times · <?=e($zone)?></legend><div class="booking-slots"><?php foreach($slots as$s):?><label><input type="radio" name="slot" value="<?=$s?>" required><span><?=e((new DateTimeImmutable('@'.$s))->setTimezone(comm_zone($zone))->format('D j M · H:i'))?></span></label><?php endforeach;?></div></fieldset>
<?php if(!$manage):?><h2>3. Your details</h2><div class="comm-fields"><label>First name<input name="first" maxlength="80" autocomplete="given-name" required></label><label>Last name<input name="last" maxlength="80" autocomplete="family-name" required></label></div><label>Email<input type="email" name="email" maxlength="254" autocomplete="email" required></label><label>What would you like to discuss?<textarea name="agenda" maxlength="1500" rows="4" required></textarea></label><div hidden aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label><input type="checkbox" name="consent" required>I agree to the use of my details for this appointment and its service notifications. <a href="<?=url('/privacy')?>">Privacy</a></label><p>This does not subscribe you to marketing emails.</p><?php endif;?><button class="wbtn primary"><?=$manage?'Confirm new time':(!empty($cfg['types'][$type]['approval'])?'Request this meeting':'Confirm booking')?></button><p class="comm-muted">The selected time is rechecked when you submit.</p></form><?php endif;?></section></div>
<?php endif;?></main><script src="<?=asset('js/communication.js')?>" defer></script>
